// Check that the number given as digits is at most limit.
//
// Both digits and limit are expected to be decimal digits
// without a sign and without leading zeros. An empty text represents zero.
//
// We compare the numbers digit by digit, since they might not fit into an integer.
//
//   - `digits`: Number to be checked
//   - `limit`: Largest allowed number
//   - Return True if digits is at most limit
func isMagnitudeAtMost(
	digits string,
	limit string,
) bool {
	if ourcommon.LenStr(digits) != ourcommon.LenStr(limit) {
		return ourcommon.LenStr(digits) < ourcommon.LenStr(limit)
	}
	for i := 0; i < ourcommon.LenStr(digits); i++ {
		digit :=
			ourcommon.ParseSafeInt(ourcommon.SliceStr(digits, int64(i), int64(i+1)))
		limitDigit :=
			ourcommon.ParseSafeInt(ourcommon.SliceStr(limit, int64(i), int64(i+1)))
		if digit != limitDigit {
			return digit < limitDigit
		}
	}
	return true
}

// Check that the integer text is within the given range.
//
// The text is expected to consist of decimal digits with an optional
// sign.
//
//   - `text`: Text to be checked
//   - `max_negative`:
//     Largest allowed magnitude of a negative number
//   - `max_positive`: Largest allowed positive number
//   - Return True if the text is within the range
func isIntegerInRange(
	text string,
	maxNegative string,
	maxPositive string,
) bool {
	digits :=
		strings.TrimLeft(strings.TrimLeft(text, "+-"), "0")
	if ourcommon.SliceStr(text, 0, 1) == "-" {
		return isMagnitudeAtMost(digits, maxNegative)
	}
	return isMagnitudeAtMost(digits, maxPositive)
}

// Get the digit at index of head followed by tail.
//
// We can not concatenate the strings, so we index into them as if they were one.
//
//   - `head`: First part of the digits
//   - `tail`: Second part of the digits
//   - `index`: Zero-based index of the digit
//   - Return The digit at index, or zero beyond the digits
func digitAt(
	head string,
	tail string,
	index int64,
) int64 {
	if index < int64(ourcommon.LenStr(head)) {
		return ourcommon.ParseSafeInt(ourcommon.SliceStr(head, index, index+1))
	}
	tailIndex := index - int64(ourcommon.LenStr(head))
	if tailIndex < int64(ourcommon.LenStr(tail)) {
		return ourcommon.ParseSafeInt(ourcommon.SliceStr(tail, tailIndex, tailIndex+1))
	}
	return 0
}

// Check that the magnitude of the decimal text is below limit.
//
// The text is expected to match the pattern of a finite `xs:double`
// or `xs:float`, i.e., a decimal with an optional sign, an optional point and
// an optional exponent. The limit is expected to be a positive integer
// without leading zeros.
//
// We compare the numbers as strings, since they do not necessarily fit into
// any native number, and parsing them to floating-point numbers would round them.
//
//   - `text`: Decimal to be checked
//   - `limit`: Exclusive upper bound on the magnitude
//   - Return True if the magnitude of text is below limit
func isDecimalMagnitudeBelow(
	text string,
	limit string,
) bool {
	unsigned := strings.TrimLeft(text, "+-")
	exponentStart := ourcommon.FindStr(unsigned, "e", 0)
	if exponentStart == -1 {
		exponentStart = ourcommon.FindStr(unsigned, "E", 0)
	}
	mantissa := unsigned
	exponentText := ""
	if exponentStart != -1 {
		mantissa = ourcommon.SliceStr(unsigned, 0, exponentStart)
		exponentText =
			ourcommon.SliceStrFrom(unsigned, exponentStart+1)
	}
	point := ourcommon.FindStr(mantissa, ".", 0)
	integerPart := mantissa
	fractionPart := ""
	if point != -1 {
		integerPart = ourcommon.SliceStr(mantissa, 0, point)
		fractionPart = ourcommon.SliceStrFrom(mantissa, point+1)
	}
	head := strings.TrimLeft(integerPart, "0")
	tail := fractionPart
	var shift int64 = int64(ourcommon.LenStr(head))
	if head == "" {
		tail = strings.TrimLeft(fractionPart, "0")
		if tail == "" {
			return true
		}
		shift =
			int64(ourcommon.LenStr(tail) - ourcommon.LenStr(fractionPart))
	}
	exponentDigits :=
		strings.TrimLeft(strings.TrimLeft(exponentText, "+-"), "0")
	if ourcommon.LenStr(exponentDigits) > 15 {
		return ourcommon.SliceStr(exponentText, 0, 1) == "-"
	}
	var exponent int64 = int64(0)
	if ourcommon.LenStr(exponentDigits) > 0 {
		exponent = ourcommon.ParseSafeInt(exponentDigits)
		if ourcommon.SliceStr(exponentText, 0, 1) == "-" {
			exponent = -exponent
		}
	}
	magnitude := exponent + shift
	if magnitude != int64(ourcommon.LenStr(limit)) {
		return magnitude < int64(ourcommon.LenStr(limit))
	}
	for i := 0; i < ourcommon.LenStr(limit); i++ {
		digit := digitAt(head, tail, int64(i))
		limitDigit :=
			ourcommon.ParseSafeInt(ourcommon.SliceStr(limit, int64(i), int64(i+1)))
		if digit != limitDigit {
			return digit < limitDigit
		}
	}
	return false
}

// Check that text is a valid `xs:double`.
//
// We check that the text matches the pattern of `xs:double`, and
// that it does not overflow, i.e., that it does not round to infinity unless it
// is `INF` or `-INF`. See [ourconstants.XsDoubleOverflowThreshold].
//
// See: https://www.w3.org/TR/xmlschema-2/#double
//
//   - `text`: Text to be checked
//   - Return True if the text is a valid `xs:double`
func IsXsDouble(
	text string,
) bool {
	if !MatchesXsDouble(text) {
		return false
	}
	switch text {
	case "INF", "-INF", "NaN":
		return true
	}
	return isDecimalMagnitudeBelow(
		text,
		ourconstants.XsDoubleOverflowThreshold,
	)
}

// Check that text is a valid `xs:float`.
//
// We check that the text matches the pattern of `xs:float`, and
// that it does not overflow, i.e., that it does not round to infinity unless it
// is `INF` or `-INF`. See [ourconstants.XsFloatOverflowThreshold].
//
// See: https://www.w3.org/TR/xmlschema-2/#float
//
//   - `text`: Text to be checked
//   - Return True if the text is a valid `xs:float`
func IsXsFloat(
	text string,
) bool {
	if !MatchesXsFloat(text) {
		return false
	}
	switch text {
	case "INF", "-INF", "NaN":
		return true
	}
	return isDecimalMagnitudeBelow(
		text,
		ourconstants.XsFloatOverflowThreshold,
	)
}

// Check that text is a valid `xs:gMonthDay`.
//
// We check that the text matches the pattern of `xs:gMonthDay`,
// and that the day exists in the month. February 29th is valid, as there is no
// year to tell otherwise.
//
// See: https://www.w3.org/TR/xmlschema-2/#gMonthDay
//
//   - `text`: Text to be checked
//   - Return True if the text is a valid `xs:gMonthDay`
func IsXsGMonthDay(
	text string,
) bool {
	return MatchesXsGMonthDay(text) &&
		isDayOfMonthValid(
			true,
			ourcommon.ParseSafeInt(ourcommon.SliceStr(text, 2, 4)),
			ourcommon.ParseSafeInt(ourcommon.SliceStr(text, 5, 7)),
		)
}

// Check that text is a valid `xs:long`.
