//
//   - `text`: Text to be checked
//   - Return True if the text is a valid `xs:long`
func IsXsLong(
	text string,
) bool {
	return MatchesXsLong(text) &&
		isIntegerInRange(
			text,
			"9223372036854775808",
			"9223372036854775807",
		)
}

