// Check that the value conforms to its valueType.
//
//   - `value`: which needs to conform
//   - `value_type`: pre-defined value type
//   - Return True if the value conforms
func ValueConsistentWithXSDType(
	value string,
	valueType ourtypes.DataTypeDefXSD,
) bool {
	switch valueType {
	case ourtypes.DataTypeDefXSDAnyURI:
		return MatchesXsAnyURI(value)
	case ourtypes.DataTypeDefXSDBase64Binary:
		return MatchesXsBase64Binary(value)
	case ourtypes.DataTypeDefXSDBoolean:
		return MatchesXsBoolean(value)
	case ourtypes.DataTypeDefXSDByte:
		return IsXsByte(value)
	case ourtypes.DataTypeDefXSDDate:
		return IsXsDate(value)
	case ourtypes.DataTypeDefXSDDateTime:
		return IsXsDateTime(value)
	case ourtypes.DataTypeDefXSDDecimal:
		return MatchesXsDecimal(value)
	case ourtypes.DataTypeDefXSDDouble:
		return IsXsDouble(value)
	case ourtypes.DataTypeDefXSDDuration:
		return MatchesXsDuration(value)
	case ourtypes.DataTypeDefXSDFloat:
		return IsXsFloat(value)
	case ourtypes.DataTypeDefXSDGDay:
		return MatchesXsGDay(value)
	case ourtypes.DataTypeDefXSDGMonth:
		return MatchesXsGMonth(value)
	case ourtypes.DataTypeDefXSDGMonthDay:
		return IsXsGMonthDay(value)
	case ourtypes.DataTypeDefXSDGYear:
		return MatchesXsGYear(value)
	case ourtypes.DataTypeDefXSDGYearMonth:
		return MatchesXsGYearMonth(value)
	case ourtypes.DataTypeDefXSDHexBinary:
		return MatchesXsHexBinary(value)
	case ourtypes.DataTypeDefXSDInt:
		return IsXsInt(value)
	case ourtypes.DataTypeDefXSDInteger:
		return MatchesXsInteger(value)
	case ourtypes.DataTypeDefXSDLong:
		return IsXsLong(value)
	case ourtypes.DataTypeDefXSDNegativeInteger:
		return MatchesXsNegativeInteger(value)
	case ourtypes.DataTypeDefXSDNonNegativeInteger:
		return MatchesXsNonNegativeInteger(value)
	case ourtypes.DataTypeDefXSDNonPositiveInteger:
		return MatchesXsNonPositiveInteger(value)
	case ourtypes.DataTypeDefXSDPositiveInteger:
		return MatchesXsPositiveInteger(value)
	case ourtypes.DataTypeDefXSDShort:
		return IsXsShort(value)
	case ourtypes.DataTypeDefXSDString:
		return MatchesXsString(value)
	case ourtypes.DataTypeDefXSDTime:
		return MatchesXsTime(value)
	case ourtypes.DataTypeDefXSDUnsignedByte:
		return IsXsUnsignedByte(value)
	case ourtypes.DataTypeDefXSDUnsignedInt:
		return IsXsUnsignedInt(value)
	case ourtypes.DataTypeDefXSDUnsignedLong:
		return IsXsUnsignedLong(value)
	case ourtypes.DataTypeDefXSDUnsignedShort:
		return IsXsUnsignedShort(value)
	}
	return false
}

// Check that the target of the model reference matches the expectedType.
func IsModelReferenceTo(
	reference ourtypes.IReference,
	expectedType ourtypes.KeyTypes,
) bool {
	return reference.Type() == ourtypes.ReferenceTypesModelReference &&
		len(reference.Keys()) != 0 &&
		reference.Keys()[len(reference.Keys())-1].Type() == expectedType
}

// Check that the target of the reference matches a [ourconstants.AASReferables].
func IsModelReferenceToReferable(
	reference ourtypes.IReference,
) bool {
	return reference.Type() == ourtypes.ReferenceTypesModelReference &&
		len(reference.Keys()) != 0 &&
		ourcommon.MapContains(
			ourconstants.AASReferables,
			reference.Keys()[len(reference.Keys())-1].Type(),
		)
}

// Check that the [ourtypes.IReferable.IDShort]'s among the referables are
// unique in their namespace.
//
// The items of the argument referables are of the type parameter ReferablesT instead of ourtypes.IReferable so that the slices of the descendants of ourtypes.IReferable can be passed without a copy, as the slices are invariant in Go.
func IDShortsAreUnique[ReferablesT ourtypes.IReferable](
	referables []ReferablesT,
) bool {
	var idShortSet map[string]struct{} = make(map[string]struct{})
	for _, referable := range referables {
		idShort := referable.IDShort()
		if idShort == nil {
			continue
		}
		if ourcommon.MapContains(
			idShortSet,
			*idShort,
		) {
			return false
		}
		idShortSet[*idShort] = struct{}{}
	}
	return true
}

// Collect the [ourtypes.IReferable.IDShort]'s of the variables values.
//
//   - `variables`:
//     Operation variables whose ID-shorts we collect
//   - `id_short_set`:
//     ID-shorts observed so far, extended in place
//   - Return False if an ID-short has been already observed
func collectUniqueIDShortsOfVariables(
	variables []ourtypes.IOperationVariable,
	idShortSet map[string]struct{},
) bool {
	if variables == nil {
		return true
	}
	for _, variable := range variables {
		idShort := variable.Value().IDShort()
		if idShort == nil {
			continue
		}
		if ourcommon.MapContains(
			idShortSet,
			*idShort,
		) {
			return false
		}
		idShortSet[*idShort] = struct{}{}
	}
	return true
}

// Check that the [ourtypes.IReferable.IDShort]'s among all the
// inputVariables, outputVariables
// and inoutputVariables are unique.
func IDShortsOfVariablesAreUnique(
	inputVariables []ourtypes.IOperationVariable,
	outputVariables []ourtypes.IOperationVariable,
	inoutputVariables []ourtypes.IOperationVariable,
) bool {
	var idShortSet map[string]struct{} = make(map[string]struct{})
	return collectUniqueIDShortsOfVariables(
		inputVariables,
		idShortSet,
	) &&
		collectUniqueIDShortsOfVariables(
			outputVariables,
			idShortSet,
		) &&
		collectUniqueIDShortsOfVariables(
			inoutputVariables,
			idShortSet,
		)
}

func constructSpecificAssetIDNameMatchesGlobalAssetID() *regexp.Regexp {
	pattern := "^[gG][lL][oO][bB][aA][lL][aA][sS][sS][eE][tT][iI][dD]$"

	return regexp.MustCompile(
		pattern,
	)
}

var specificAssetIDNameMatchesGlobalAssetIDRe = constructSpecificAssetIDNameMatchesGlobalAssetID()

// Check whether name is the reserved global asset ID key.
func SpecificAssetIDNameMatchesGlobalAssetID(name string) bool {
	return specificAssetIDNameMatchesGlobalAssetIDRe.MatchString(
		name,
	)
}

// Check whether element or its descendants have template qualifiers.
func SubmodelElementHasTemplateQualifierInTree(
	element ourtypes.ISubmodelElement,
) bool {
	if (element.Qualifiers() != nil) &&
		ourcommon.Some(
			func(qualifier ourtypes.IQualifier) bool {
				return qualifier.KindOrDefault() == ourtypes.QualifierKindTemplateQualifier
			},
			element.Qualifiers(),
		) {
		return true
	}
	if ourtypes.IsSubmodelElementList(element) {
		return (element.(ourtypes.ISubmodelElementList).Value() != nil) &&
			ourcommon.Some(
				func(child ourtypes.ISubmodelElement) bool {
					return SubmodelElementHasTemplateQualifierInTree(child)
				},
				element.(ourtypes.ISubmodelElementList).Value(),
			)
	}
	if ourtypes.IsSubmodelElementCollection(element) {
		return (element.(ourtypes.ISubmodelElementCollection).Value() != nil) &&
			ourcommon.Some(
				func(child ourtypes.ISubmodelElement) bool {
					return SubmodelElementHasTemplateQualifierInTree(child)
				},
				element.(ourtypes.ISubmodelElementCollection).Value(),
			)
	}
	if ourtypes.IsEntity(element) {
		return (element.(ourtypes.IEntity).Statements() != nil) &&
			ourcommon.Some(
				func(child ourtypes.ISubmodelElement) bool {
					return SubmodelElementHasTemplateQualifierInTree(child)
				},
				element.(ourtypes.IEntity).Statements(),
			)
	}
	if ourtypes.IsAnnotatedRelationshipElement(element) {
		return (element.(ourtypes.IAnnotatedRelationshipElement).Annotations() != nil) &&
			ourcommon.Some(
				func(child ourtypes.IDataElement) bool {
					return SubmodelElementHasTemplateQualifierInTree(child)
				},
				element.(ourtypes.IAnnotatedRelationshipElement).Annotations(),
			)
	}
	if ourtypes.IsOperation(element) {
	}
	return false
}

// Check that elements have no template qualifiers in their trees.
//
// The items of the argument elements are of the type parameter ElementsT instead of ourtypes.ISubmodelElement so that the slices of the descendants of ourtypes.ISubmodelElement can be passed without a copy, as the slices are invariant in Go.
func SubmodelElementsHaveNoTemplateQualifiers[ElementsT ourtypes.ISubmodelElement](
	elements []ElementsT,
) bool {
	return ourcommon.All(
		func(element ElementsT) bool {
			return !SubmodelElementHasTemplateQualifierInTree(element)
		},
		elements,
	)
}

// Recursively check that submodel element lists have exactly one child.
func SubmodelElementListsHaveExactlyOneElementInTree(
	element ourtypes.ISubmodelElement,
) bool {
	if ourtypes.IsSubmodelElementList(element) {
		return (element.(ourtypes.ISubmodelElementList).Value() != nil) &&
			len(element.(ourtypes.ISubmodelElementList).Value()) == 1 &&
			ourcommon.All(
				func(child ourtypes.ISubmodelElement) bool {
					return SubmodelElementListsHaveExactlyOneElementInTree(
						child,
					)
				},
				element.(ourtypes.ISubmodelElementList).Value(),
			)
	}
	if ourtypes.IsSubmodelElementCollection(element) {
		return (element.(ourtypes.ISubmodelElementCollection).Value() == nil) ||
			ourcommon.All(
				func(child ourtypes.ISubmodelElement) bool {
					return SubmodelElementListsHaveExactlyOneElementInTree(
						child,
					)
				},
				element.(ourtypes.ISubmodelElementCollection).Value(),
			)
	}
	if ourtypes.IsEntity(element) {
		return (element.(ourtypes.IEntity).Statements() == nil) ||
			ourcommon.All(
				func(child ourtypes.ISubmodelElement) bool {
					return SubmodelElementListsHaveExactlyOneElementInTree(
						child,
					)
				},
				element.(ourtypes.IEntity).Statements(),
			)
	}
	if ourtypes.IsAnnotatedRelationshipElement(element) {
		return (element.(ourtypes.IAnnotatedRelationshipElement).Annotations() == nil) ||
			ourcommon.All(
				func(child ourtypes.IDataElement) bool {
					return SubmodelElementListsHaveExactlyOneElementInTree(
						child,
					)
				},
				element.(ourtypes.IAnnotatedRelationshipElement).Annotations(),
			)
	}
	return true
}

// Check that all submodel element lists among elements have one item.
//
// The items of the argument elements are of the type parameter ElementsT instead of ourtypes.ISubmodelElement so that the slices of the descendants of ourtypes.ISubmodelElement can be passed without a copy, as the slices are invariant in Go.
func SubmodelElementListsInSubmodelElementsHaveExactlyOneElement[ElementsT ourtypes.ISubmodelElement](
	elements []ElementsT,
) bool {
	return ourcommon.All(
		func(element ElementsT) bool {
			return SubmodelElementListsHaveExactlyOneElementInTree(
				element,
			)
		},
		elements,
	)
}

// Check that submodel element lists in operation variables have one item.
func SubmodelElementListsInOperationVariablesHaveExactlyOneElement(
	inputVariables []ourtypes.IOperationVariable,
	outputVariables []ourtypes.IOperationVariable,
	inoutputVariables []ourtypes.IOperationVariable,
) bool {
	return ((inputVariables == nil) ||
		ourcommon.All(
			func(variable ourtypes.IOperationVariable) bool {
				return SubmodelElementListsHaveExactlyOneElementInTree(
					variable.Value(),
				)
			},
			inputVariables,
		)) &&
		((outputVariables == nil) ||
			ourcommon.All(
				func(variable ourtypes.IOperationVariable) bool {
					return SubmodelElementListsHaveExactlyOneElementInTree(
						variable.Value(),
					)
				},
				outputVariables,
			)) &&
		((inoutputVariables == nil) ||
			ourcommon.All(
				func(variable ourtypes.IOperationVariable) bool {
					return SubmodelElementListsHaveExactlyOneElementInTree(
						variable.Value(),
					)
				},
				inoutputVariables,
			))
}

// Check that the extension names are unique.
func ExtensionNamesAreUnique(
	extensions []ourtypes.IExtension,
) bool {
	var nameSet map[string]struct{} = make(map[string]struct{})
	for _, extension := range extensions {
		if ourcommon.MapContains(
			nameSet,
			extension.Name(),
		) {
			return false
		}
		nameSet[extension.Name()] = struct{}{}
	}
	return true
}

// Check that all semantic IDs are identical, if specified.
//
// The items of the argument elements are of the type parameter ElementsT instead of ourtypes.ISubmodelElement so that the slices of the descendants of ourtypes.ISubmodelElement can be passed without a copy, as the slices are invariant in Go.
func SubmodelElementsHaveIdenticalSemanticIDs[ElementsT ourtypes.ISubmodelElement](
	elements []ElementsT,
) bool {
	var thatSemanticID ourtypes.IReference = nil
	for _, element := range elements {
		thisSemanticID := element.SemanticID()
		if thisSemanticID == nil {
			continue
		}
		if thatSemanticID == nil {
			thatSemanticID = thisSemanticID
		} else if !ReferenceKeyValuesEqual(
			thatSemanticID,
			thisSemanticID,
		) {
			return false
		}
	}
	return true
}

// Check that the run-time type of the element coincides with
// elementType.
func SubmodelElementIsOfType(
	element ourtypes.ISubmodelElement,
	elementType ourtypes.AASSubmodelElements,
) bool {
	switch elementType {
	case ourtypes.AASSubmodelElementsAnnotatedRelationshipElement:
		return ourtypes.IsAnnotatedRelationshipElement(element)
	case ourtypes.AASSubmodelElementsBasicEventElement:
		return ourtypes.IsBasicEventElement(element)
	case ourtypes.AASSubmodelElementsBlob:
		return ourtypes.IsBlob(element)
	case ourtypes.AASSubmodelElementsCapability:
		return ourtypes.IsCapability(element)
	case ourtypes.AASSubmodelElementsDataElement:
		return ourtypes.IsDataElement(element)
	case ourtypes.AASSubmodelElementsEntity:
		return ourtypes.IsEntity(element)
	case ourtypes.AASSubmodelElementsEventElement:
		return ourtypes.IsEventElement(element)
	case ourtypes.AASSubmodelElementsFile:
		return ourtypes.IsFile(element)
	case ourtypes.AASSubmodelElementsMultiLanguageProperty:
		return ourtypes.IsMultiLanguageProperty(element)
	case ourtypes.AASSubmodelElementsOperation:
		return ourtypes.IsOperation(element)
	case ourtypes.AASSubmodelElementsProperty:
		return ourtypes.IsProperty(element)
	case ourtypes.AASSubmodelElementsRange:
		return ourtypes.IsRange(element)
	case ourtypes.AASSubmodelElementsReferenceElement:
		return ourtypes.IsReferenceElement(element)
	case ourtypes.AASSubmodelElementsRelationshipElement:
		return ourtypes.IsRelationshipElement(element)
	case ourtypes.AASSubmodelElementsSubmodelElement:
		return true
	case ourtypes.AASSubmodelElementsSubmodelElementList:
		return ourtypes.IsSubmodelElementList(element)
	case ourtypes.AASSubmodelElementsSubmodelElementCollection:
		return ourtypes.IsSubmodelElementCollection(element)
	}
	return false
}

// Check that all the elements have the valueType.
//
// The items of the argument elements are of the type parameter ElementsT instead of ourtypes.ISubmodelElement so that the slices of the descendants of ourtypes.ISubmodelElement can be passed without a copy, as the slices are invariant in Go.
func PropertiesOrRangesHaveValueType[ElementsT ourtypes.ISubmodelElement](
	elements []ElementsT,
	valueType ourtypes.DataTypeDefXSD,
) bool {
	for _, element := range elements {
		if ourtypes.IsProperty(element) &&
			any(element).(ourtypes.IProperty).ValueType() != valueType {
			return false
		}
		if ourtypes.IsRange(element) &&
			any(element).(ourtypes.IRange).ValueType() != valueType {
			return false
		}
	}
	return true
}

// Check that the two references are equal by comparing their key values.
func ReferenceKeyValuesEqual(
	that ourtypes.IReference,
	other ourtypes.IReference,
) bool {
	if len(that.Keys()) != len(other.Keys()) {
		return false
	}
	for i := 0; i < len(that.Keys()); i++ {
		if that.Keys()[i].Value() != other.Keys()[i].Value() {
			return false
		}
	}
	return true
}

