// Check that the [ourtypes.IDataSpecificationIEC61360.Definition] is defined
// for all data specifications whose content is given as IEC 61360 at least in English.
func DataSpecificationIEC61360sHaveDefinitionAtLeastInEnglish(
	embeddedDataSpecifications []ourtypes.IEmbeddedDataSpecification,
) bool {
	for _, dataSpecification := range embeddedDataSpecifications {
		content := dataSpecification.DataSpecificationContent()
		if !ourtypes.IsDataSpecificationIEC61360(content) {
			continue
		}
		definition :=
			content.(ourtypes.IDataSpecificationIEC61360).Definition()
		if definition == nil {
			return false
		}
		if !ourcommon.Some(
			func(langString ourtypes.ILangStringDefinitionTypeIEC61360) bool {
				return IsBCP47ForEnglish(langString.Language())
			},
			definition,
		) {
			return false
		}
	}
	return true
}

func constructIsBCP47ForEnglish() *regexp.Regexp {
	pattern := "^(en|EN)(-.*)?$"

	return regexp.MustCompile(
		pattern,
	)
}

var isBCP47ForEnglishRe = constructIsBCP47ForEnglish()

// Check that the text corresponds to a BCP47 code for english.
func IsBCP47ForEnglish(text string) bool {
	return isBCP47ForEnglishRe.MatchString(
		text,
	)
}

func constructMatchesPathItem() *regexp.Regexp {
	pattern := "^(([A-Za-z][A-Za-z0-9_]+)|(\\[[0-9]+\\]))((\\.[A-Za-z][A-Za-z0-9_]+)|(\\[[0-9]+\\]))*$"

	return regexp.MustCompile(
		pattern,
	)
}

var matchesPathItemRe = constructMatchesPathItem()

// Check that text is a valid idShortPath.
//
// An idShortPath is a chain of idShorts or SubmodelElementList-indexes
// which points to an element within a hierarchy of elements, e.g.,
// `sme1.sme2[0].p1`.
func MatchesPathItem(text string) bool {
	return matchesPathItemRe.MatchString(
		text,
	)
}

func constructMatchesFieldIdentifier() *regexp.Regexp {
	arrayIndex := "(0|[1-9][0-9]*)"
	optionalIndex := ourcommon.Concat(
		"\\[",
		arrayIndex,
		"?\\]",
	)
	referenceClause := ourcommon.Concat(
		"(type|keys",
		optionalIndex,
		"\\.(type|value))",
	)
	semanticIdClause := ourcommon.Concat(
		"semanticId(\\.",
		referenceClause,
		")?",
	)
	supplementalSemanticIdClause := ourcommon.Concat(
		"supplementalSemanticIds(",
		optionalIndex,
		")?(\\.",
		referenceClause,
		")?",
	)
	specificAssetIdsClause := ourcommon.Concat(
		"specificAssetIds",
		optionalIndex,
		"\\.(name|value|externalSubjectId(\\.",
		referenceClause,
		")?)",
	)
	endpointClause := ourcommon.Concat(
		"endpoints",
		optionalIndex,
		"\\.(interface|protocolinformation\\.href)",
	)
	smDescriptorClause := ourcommon.Concat(
		"(",
		semanticIdClause,
		"|",
		supplementalSemanticIdClause,
		"|idShort|id|",
		endpointClause,
		")",
	)
	idShort := "[A-Za-z]([A-Za-z0-9_-]*[A-Za-z0-9_])?"
	idShortPathSegment := ourcommon.Concat(
		idShort,
		"(",
		optionalIndex,
		")*",
	)
	idShortPath := ourcommon.Concat(
		idShortPathSegment,
		"(\\.",
		idShortPathSegment,
		")*",
	)
	fieldsAas := ourcommon.Concat(
		"(idShort|id|assetInformation\\.assetKind|assetInformation\\.assetType|assetInformation\\.globalAssetId|assetInformation\\.",
		specificAssetIdsClause,
		"|submodels",
		optionalIndex,
		"(\\.",
		referenceClause,
		")?)",
	)
	fieldsSm := ourcommon.Concat(
		"(",
		semanticIdClause,
		"|",
		supplementalSemanticIdClause,
		"|idShort|id)",
	)
	fieldsSme := ourcommon.Concat(
		"(",
		semanticIdClause,
		"|",
		supplementalSemanticIdClause,
		"|idShort|value|valueType|language)",
	)
	fieldsCd := "(idShort|id)"
	fieldsAasDescriptor := ourcommon.Concat(
		"(idShort|id|assetKind|assetType|globalAssetId|",
		specificAssetIdsClause,
		"|",
		endpointClause,
		"|submodelDescriptors",
		optionalIndex,
		"\\.",
		smDescriptorClause,
		")",
	)
	pattern := ourcommon.Concat(
		"^(\\$aas#",
		fieldsAas,
		"|\\$sm#",
		fieldsSm,
		"|\\$sme(\\.",
		idShortPath,
		")?#",
		fieldsSme,
		"|\\$cd#",
		fieldsCd,
		"|\\$aasdesc#",
		fieldsAasDescriptor,
		"|\\$smdesc#",
		smDescriptorClause,
		")$",
	)

	return regexp.MustCompile(
		pattern,
	)
}

var matchesFieldIdentifierRe = constructMatchesFieldIdentifier()

// Check that text is a valid field identifier of the query language.
//
// A field identifier starts with a root (`$aas`, `$sm`, `$sme`, `$cd`,
// `$aasdesc` or `$smdesc`), optionally followed by an idShortPath in case
// of `$sme`, and ends with an attribute declaration after `#`, e.g.,
// `$sme.someCollection.someProperty#value`.
//
// See:
// https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#query-grammar
//
//   - `text`: Text to be checked
//   - Return True if the text conforms to the pattern
func MatchesFieldIdentifier(text string) bool {
	return matchesFieldIdentifierRe.MatchString(
		text,
	)
}

func constructMatchesFragmentFieldIdentifier() *regexp.Regexp {
	arrayIndex := "(0|[1-9][0-9]*)"
	optionalIndex := ourcommon.Concat(
		"\\[",
		arrayIndex,
		"?\\]",
	)
	referenceClause := ourcommon.Concat(
		"keys(",
		optionalIndex,
		")?",
	)
	semanticIdClause := ourcommon.Concat(
		"semanticId(\\.",
		referenceClause,
		")?",
	)
	supplementalSemanticIdClause := ourcommon.Concat(
		"supplementalSemanticIds(",
		optionalIndex,
		"(\\.",
		referenceClause,
		")?)?",
	)
	specificAssetIdsClause := ourcommon.Concat(
		"specificAssetIds(",
		optionalIndex,
		"(\\.externalSubjectId(\\.",
		referenceClause,
		")?)?)?",
	)
	submodelsClause := ourcommon.Concat(
		"submodels(",
		optionalIndex,
		"(\\.",
		referenceClause,
		")?)?",
	)
	endpointClause := ourcommon.Concat(
		"endpoints(",
		optionalIndex,
		")?",
	)
	smDescriptorClause := ourcommon.Concat(
		"(",
		semanticIdClause,
		"|",
		supplementalSemanticIdClause,
		"|idShort|",
		endpointClause,
		")",
	)
	submodelDescriptorsClause := ourcommon.Concat(
		"submodelDescriptors(",
		optionalIndex,
		"(\\.",
		smDescriptorClause,
		")?)?",
	)
	idShort := "[A-Za-z]([A-Za-z0-9_-]*[A-Za-z0-9_])?"
	idShortPathSegment := ourcommon.Concat(
		idShort,
		"(",
		optionalIndex,
		")*",
	)
	idShortPath := ourcommon.Concat(
		idShortPathSegment,
		"(\\.",
		idShortPathSegment,
		")*",
	)
	fieldsAas := ourcommon.Concat(
		"(idShort|assetInformation\\.assetType|assetInformation\\.globalAssetId|assetInformation\\.",
		specificAssetIdsClause,
		"|",
		submodelsClause,
		")",
	)
	fieldsSm := ourcommon.Concat(
		"(",
		semanticIdClause,
		"|",
		supplementalSemanticIdClause,
		"|idShort)",
	)
	fieldsSme := ourcommon.Concat(
		"(",
		semanticIdClause,
		"|",
		supplementalSemanticIdClause,
		"|idShort|value|valueType|language)",
	)
	fieldsAasDescriptor := ourcommon.Concat(
		"(idShort|description|displayName|extension|administration|assetKind|assetType|globalAssetId|",
		specificAssetIdsClause,
		"|",
		endpointClause,
		"|",
		submodelDescriptorsClause,
		")",
	)
	pattern := ourcommon.Concat(
		"^(\\$aas#",
		fieldsAas,
		"|\\$sm#",
		fieldsSm,
		"|\\$sme(\\.",
		idShortPath,
		")?(#",
		fieldsSme,
		")?|\\$cd#idShort|\\$aasdesc#",
		fieldsAasDescriptor,
		"|\\$smdesc#",
		smDescriptorClause,
		")$",
	)

	return regexp.MustCompile(
		pattern,
	)
}

var matchesFragmentFieldIdentifierRe = constructMatchesFragmentFieldIdentifier()

// Check that text is a valid fragment field identifier.
//
// A fragment field identifier points to the part of the returned data which
// should be filtered, e.g., `$aas#assetInformation.specificAssetIds[]`
// or `$sme.someCollection`.
//
// See:
// https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#query-grammar
//
//   - `text`: Text to be checked
//   - Return True if the text conforms to the pattern
func MatchesFragmentFieldIdentifier(text string) bool {
	return matchesFragmentFieldIdentifierRe.MatchString(
		text,
	)
}

