func constructMatchesDateTimeLiteral() *regexp.Regexp {
	digit := "[0-9]"
	monthWith31Days := ourcommon.Concat(
		"(0[13578]|1[02])-(0[1-9]|[12]",
		digit,
		"|3[01])",
	)
	monthWith30Days := ourcommon.Concat(
		"(0[469]|11)-(0[1-9]|[12]",
		digit,
		"|30)",
	)
	february := ourcommon.Concat(
		"02-(0[1-9]|1",
		digit,
		"|2[0-8])",
	)
	commonDate := ourcommon.Concat(
		digit,
		"{4}-(",
		monthWith31Days,
		"|",
		monthWith30Days,
		"|",
		february,
		")",
	)
	leapYear := ourcommon.Concat(
		"(",
		digit,
		"{2}(0[48]|[2468][048]|[13579][26])|([02468][048]|[13579][26])00)",
	)
	leapDay := ourcommon.Concat(
		leapYear,
		"-02-29",
	)
	time := ourcommon.Concat(
		"(([01]",
		digit,
		"|2[0-3]):[0-5]",
		digit,
		"(:[0-5]",
		digit,
		")?(\\.",
		digit,
		"+)?|24:00(:00)?(\\.0+)?)",
	)
	timezone := ourcommon.Concat(
		"(Z|[+-]((0",
		digit,
		"|1[0-3]):[0-5]",
		digit,
		"|14:00))",
	)
	pattern := ourcommon.Concat(
		"^((",
		commonDate,
		")|(",
		leapDay,
		"))T?",
		time,
		timezone,
		"?$",
	)

	return regexp.MustCompile(
		pattern,
	)
}

var matchesDateTimeLiteralRe = constructMatchesDateTimeLiteral()

// Check that text is a valid date-time literal of the query language.
//
// A date-time literal is a valid calendar date, followed by an optional `T`
// separator, the time and an optional time zone, e.g.,
// `2024-02-29T12:00:00Z`.
//
//   - `text`: Text to be checked
//   - Return True if the text conforms to the pattern
func MatchesDateTimeLiteral(text string) bool {
	return matchesDateTimeLiteralRe.MatchString(
		text,
	)
}

func constructMatchesTimeLiteral() *regexp.Regexp {
	digit := "[0-9]"
	time := ourcommon.Concat(
		"(([01]",
		digit,
		"|2[0-3]):[0-5]",
		digit,
		"(:[0-5]",
		digit,
		")?(\\.",
		digit,
		"+)?|24:00(:00)?(\\.0+)?)",
	)
	timezone := ourcommon.Concat(
		"(Z|[+-]((0",
		digit,
		"|1[0-3]):[0-5]",
		digit,
		"|14:00))",
	)
	pattern := ourcommon.Concat(
		"^",
		time,
		timezone,
		"?$",
	)

	return regexp.MustCompile(
		pattern,
	)
}

var matchesTimeLiteralRe = constructMatchesTimeLiteral()

// Check that text is a valid time literal of the query language.
//
// A time literal is given as `HH:MM`, `HH:MM:SS`, optionally with
// fractional seconds and an optional time zone, e.g., `12:00:00+01:00`.
//
//   - `text`: Text to be checked
//   - Return True if the text conforms to the pattern
func MatchesTimeLiteral(text string) bool {
	return matchesTimeLiteralRe.MatchString(
		text,
	)
}

func constructMatchesReferenceIdentifier() *regexp.Regexp {
	arrayIndex := "(0|[1-9][0-9]*)"
	optionalIndex := ourcommon.Concat(
		"\\[",
		arrayIndex,
		"?\\]",
	)
	referenceClause := ourcommon.Concat(
		"(type|keys",
		optionalIndex,
		"\\.(type|value))",
	)
	semanticIdClause := ourcommon.Concat(
		"semanticId(\\.",
		referenceClause,
		")?",
	)
	supplementalSemanticIdClause := ourcommon.Concat(
		"supplementalSemanticIds(",
		optionalIndex,
		")?(\\.",
		referenceClause,
		")?",
	)
	specificAssetIdsClause := ourcommon.Concat(
		"specificAssetIds",
		optionalIndex,
		"\\.(name|value|externalSubjectId(\\.",
		referenceClause,
		")?)",
	)
	idShort := "[A-Za-z]([A-Za-z0-9_-]*[A-Za-z0-9_])?"
	idShortPathSegment := ourcommon.Concat(
		idShort,
		"(",
		optionalIndex,
		")*",
	)
	idShortPath := ourcommon.Concat(
		idShortPathSegment,
		"(\\.",
		idShortPathSegment,
		")*",
	)
	identifierCharacter := "([\\x{9}\\x{a}\\x{d}\\x{20}-\\x{21}\\x{23}-\\x{5b}\\x{5d}-\\x{d7ff}\\x{e000}-\\x{fffd}\\x{10000}-\\x{10ffff}]|\\\\[\"\\\\])"
	identifierInstance := ourcommon.Concat(
		"\\(\"",
		identifierCharacter,
		"+\"\\)",
	)
	fieldsAas := ourcommon.Concat(
		"(idShort|id|assetInformation\\.assetKind|assetInformation\\.assetType|assetInformation\\.globalAssetId|assetInformation\\.",
		specificAssetIdsClause,
		"|submodels",
		optionalIndex,
		"(\\.",
		referenceClause,
		")?)",
	)
	fieldsSm := ourcommon.Concat(
		"(",
		semanticIdClause,
		"|",
		supplementalSemanticIdClause,
		"|idShort|id)",
	)
	fieldsSme := ourcommon.Concat(
		"(",
		semanticIdClause,
		"|",
		supplementalSemanticIdClause,
		"|idShort|value|valueType|language)",
	)
	pattern := ourcommon.Concat(
		"^(\\$aas",
		identifierInstance,
		"#",
		fieldsAas,
		"|\\$sm",
		identifierInstance,
		"#",
		fieldsSm,
		"|\\$cd",
		identifierInstance,
		"#(idShort|id)|\\$sme",
		identifierInstance,
		"\\.",
		idShortPath,
		"#",
		fieldsSme,
		")$",
	)

	return regexp.MustCompile(
		pattern,
	)
}

var matchesReferenceIdentifierRe = constructMatchesReferenceIdentifier()

// Check that text is a valid reference identifier.
//
// A reference identifier points to an attribute of a specific instance given
// by its identifier, e.g., `$sm("https://example.com/sm")#idShort` or
// `$sme("https://example.com/sm").someProperty#value`. A quotation mark and
// a reverse solidus in the identifier are escaped as `\"` and `\\`,
// respectively.
//
// See:
// https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#query-grammar
//
//   - `text`: Text to be checked
//   - Return True if the text conforms to the pattern
func MatchesReferenceIdentifier(text string) bool {
	return matchesReferenceIdentifierRe.MatchString(
		text,
	)
}

// Check that value can be used as an operand of valueType.
//
// Following the normative JSON schema of the query language, a field is
// implicitly cast to the type of the other operand, and can hence be used as
// an operand of any type. A global attribute giving a date and time
// (`LOCALNOW`, `UTCNOW` or `CLIENTNOW`) can be used both as a string and
// as a date-time, while all the other attributes are strings.
//
// See:
// https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema
//
//   - `value`: Operand of a comparison
//   - `value_type`:
//     One of `string`, `number`, `hex`, `boolean`, `date_time`
//     or `time`
//   - Return True if value can be used as valueType
func canBeOfType(
	value *ourtypes.Value,
	valueType string,
) bool {
	if ourtypes.IsFieldOperand(value.Underlying()) {
		return true
	}
	if ourtypes.IsAttributeOperand(value.Underlying()) {
		if valueType == "string" {
			return true
		}
		attribute :=
			value.Underlying().(ourtypes.IAttributeOperand).Attribute()
		return valueType == "date_time" &&
			ourtypes.IsGlobalAttribute(attribute.Underlying()) &&
			(attribute.Underlying().(ourtypes.IGlobalAttribute).Kind() == ourtypes.GlobalAttributeKindLocalNow ||
				attribute.Underlying().(ourtypes.IGlobalAttribute).Kind() == ourtypes.GlobalAttributeKindUTCNow ||
				attribute.Underlying().(ourtypes.IGlobalAttribute).Kind() == ourtypes.GlobalAttributeKindClientNow)
	}
	if ourtypes.IsStringLiteral(value.Underlying()) ||
		ourtypes.IsStringCast(value.Underlying()) {
		return valueType == "string"
	}
	if ourtypes.IsNumberLiteral(value.Underlying()) ||
		ourtypes.IsNumberCast(value.Underlying()) ||
		ourtypes.IsDayOfWeek(value.Underlying()) ||
		ourtypes.IsDayOfMonth(value.Underlying()) ||
		ourtypes.IsMonth(value.Underlying()) ||
		ourtypes.IsYear(value.Underlying()) {
		return valueType == "number"
	}
	if ourtypes.IsHexLiteral(value.Underlying()) ||
		ourtypes.IsHexCast(value.Underlying()) {
		return valueType == "hex"
	}
	if ourtypes.IsBooleanLiteral(value.Underlying()) ||
		ourtypes.IsBooleanCast(value.Underlying()) {
		return valueType == "boolean"
	}
	if ourtypes.IsDateTimeLiteral(value.Underlying()) ||
		ourtypes.IsDateTimeCast(value.Underlying()) {
		return valueType == "date_time"
	}
	if ourtypes.IsTimeLiteral(value.Underlying()) ||
		ourtypes.IsTimeCast(value.Underlying()) {
		return valueType == "time"
	}
	return false
}

// Check that left and right can be compared for
// (in)equality.
//
// Following the normative JSON schema of the query language, the two operands
// need to be of the same type: a string, a number, a hexadecimal, a boolean,
// a date-time or a time. A field is implicitly cast to the type of the other
// operand, and can hence be compared with an operand of any type. A global
// attribute giving a date and time (`LOCALNOW`, `UTCNOW` or `CLIENTNOW`)
// can be used both as a string and as a date-time.
//
// See:
// https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema
//
//   - `left`: First operand of the comparison
//   - `right`: Second operand of the comparison
//   - Return
//     True if the operands can be compared for (in)equality
func AreEqualityComparable(
	left *ourtypes.Value,
	right *ourtypes.Value,
) bool {
	return (canBeOfType(left, "string") &&
		canBeOfType(right, "string")) ||
		(canBeOfType(left, "number") &&
			canBeOfType(right, "number")) ||
		(canBeOfType(left, "hex") &&
			canBeOfType(right, "hex")) ||
		(canBeOfType(left, "boolean") &&
			canBeOfType(right, "boolean")) ||
		(canBeOfType(left, "date_time") &&
			canBeOfType(right, "date_time")) ||
		(canBeOfType(left, "time") &&
			canBeOfType(right, "time"))
}

// Check that left and right can be compared by order.
//
// The operands need to be comparable for (in)equality (see
// `are_equality_comparable`), but booleans can not be ordered.
//
// See:
// https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema
//
//   - `left`: First operand of the comparison
//   - `right`: Second operand of the comparison
//   - Return True if the operands can be compared by order
func AreOrderComparable(
	left *ourtypes.Value,
	right *ourtypes.Value,
) bool {
	return AreEqualityComparable(left, right) &&
		(!(ourtypes.IsBooleanLiteral(left.Underlying()) ||
			ourtypes.IsBooleanCast(left.Underlying()))) &&
		(!(ourtypes.IsBooleanLiteral(right.Underlying()) ||
			ourtypes.IsBooleanCast(right.Underlying())))
}

// Sort the keys of `that` so that the errors come in a stable order,
// as the iteration order of a Go map is deliberately random.
func sortedKeysOfJsonObject(that ourtypes.JsonObject) []string {
	keys := make([]string, 0, len(that))
	for key := range that {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

// Verify that `value` is a JSON-able value, at any depth.
//
// The path of an error is relative to `value`, and the caller is expected to
// prepend the way to it.
func verifyJsonValue(
	value ourtypes.JsonValue,
	onError func(*VerificationError) bool,
) (abort bool) {
	if value == nil {
		return onError(
			newVerificationError(
				"Expected a JSON-able value, but got a nil",
			),
		)
	}

	switch casted := value.(type) {
	case bool:
		return false

	case string:
		return false

	case float64:
		// NOTE (mristin):
		// JSON knows neither an infinity nor a not-a-number, so neither is
		// a JSON-able value, even though a float64 holds either.
		if math.IsInf(casted, 0) || math.IsNaN(casted) {
			return onError(
				newVerificationError(
					fmt.Sprintf(
						"Expected a JSON-able value, but got the number %v, "+
							"which is neither finite nor representable in JSON",
						casted,
					),
				),
			)
		}
		return false

	case ourtypes.JsonArray:
		for i, item := range casted {
			abort = verifyJsonValue(
				item,
				func(err *VerificationError) bool {
					err.Path.PrependIndex(
						&ourreporting.IndexSegment{
							Index: i,
						},
					)

					return onError(err)
				},
			)
			if abort {
				return
			}
		}
		return false

	case ourtypes.JsonObject:
		for _, key := range sortedKeysOfJsonObject(casted) {
			abort = verifyJsonValue(
				casted[key],
				func(err *VerificationError) bool {
					err.Path.PrependKey(
						&ourreporting.KeySegment{
							Key: key,
						},
					)

					return onError(err)
				},
			)
			if abort {
				return
			}
		}
		return false

	default:
		return onError(
			newVerificationError(
				fmt.Sprintf(
					"Expected a JSON-able value (a bool, a float64, a string, "+
						"a JsonArray or a JsonObject), but got: %T",
					value,
				),
			),
		)
	}
}

// Verify that `value` is a JSON-able array.
func verifyJsonArray(
	value ourtypes.JsonArray,
	onError func(*VerificationError) bool,
) (abort bool) {
	if value == nil {
		return onError(
			newVerificationError(
				"Expected a JSON-able array, but got a nil",
			),
		)
	}

	return verifyJsonValue(value, onError)
}

// Verify that `value` is a JSON-able object.
func verifyJsonObject(
	value ourtypes.JsonObject,
	onError func(*VerificationError) bool,
) (abort bool) {
	if value == nil {
		return onError(
			newVerificationError(
				"Expected a JSON-able object, but got a nil",
			),
		)
	}

	return verifyJsonValue(value, onError)
}

// Verify `that` instance of [ourtypes.IExtension].
//
// You have to supply the callback `onError` to iterate over the errors.
// If `onError` returns abort `true`, this function will abort
// further verification as well, and return abort `true`. Otherwise,
// abort `false` is returned.
func VerifyExtension(
	that ourtypes.IExtension,
	onError func(*VerificationError) bool,
) (abort bool) {
	abort = false

	if !(!(that.SupplementalSemanticIDs() != nil) ||
		(len(that.SupplementalSemanticIDs()) >= 1)) {
		abort = onError(
			newVerificationError(
				"Supplemental semantic IDs must be either not set or have at " +
					"least one item.",
			),
		)
		if abort {
			return
		}
	}

	if !(!(that.SupplementalSemanticIDs() != nil) ||
		(that.SemanticID() != nil)) {
		abort = onError(
			newVerificationError(
				"Constraint AASd-118: If there are supplemental semantic IDs " +
					"defined then there shall be also a main semantic ID.",
			),
		)
		if abort {
			return
		}
	}

	if !(!(that.RefersTo() != nil) ||
		(len(that.RefersTo()) >= 1)) {
		abort = onError(
			newVerificationError(
				"Refers-to must be either not set or have at least one item."),
		)
		if abort {
			return
		}
	}

	if !(!(that.Value() != nil) ||
		ValueConsistentWithXSDType(
			*that.Value(),
			that.ValueTypeOrDefault(),
		)) {
		abort = onError(
			newVerificationError(
				"The value must match the value type."),
		)
		if abort {
			return
		}
	}

	if that.SemanticID() != nil {
		abort = Verify(
			that.SemanticID(),
			func(err *VerificationError) bool {
				err.Path.PrependName(
					&ourreporting.NameSegment{
						Name: "SemanticID",
					},
				)
				return onError(err)
			},
		)
		if abort {
			return
		}
	}

	if that.SupplementalSemanticIDs() != nil {
		abort = verifyListOf_IReference(
			that.SupplementalSemanticIDs(),
			func(err *VerificationError) bool {
				err.Path.PrependName(
					&ourreporting.NameSegment{
						Name: "SupplementalSemanticIDs",
					},
				)
				return onError(err)
			},
		)
		if abort {
			return
		}
	}

	abort = VerifyNameType(
		that.Name(),
		func(err *VerificationError) bool {
			err.Path.PrependName(
				&ourreporting.NameSegment{
					Name: "Name",
				},
			)
			return onError(err)
		},
	)
	if abort {
		return
	}

	if that.ValueType() != nil {
		abort = VerifyDataTypeDefXSD(
			*that.ValueType(),
			func(err *VerificationError) bool {
				err.Path.PrependName(
					&ourreporting.NameSegment{
						Name: "ValueType",
					},
				)
				return onError(err)
			},
		)
		if abort {
			return
		}
	}

	if that.Value() != nil {
		abort = VerifyValueDataType(
			*that.Value(),
			func(err *VerificationError) bool {
				err.Path.PrependName(
					&ourreporting.NameSegment{
						Name: "Value",
					},
				)
				return onError(err)
			},
		)
		if abort {
			return
		}
	}

	if that.RefersTo() != nil {
		abort = verifyListOf_IReference(
			that.RefersTo(),
			func(err *VerificationError) bool {
				err.Path.PrependName(
					&ourreporting.NameSegment{
						Name: "RefersTo",
					},
				)
				return onError(err)
			},
		)
		if abort {
			return
		}
	}

	return
}

